export type V8PublicationState = "verified" | "client-supplied" | "pending-review";
export type V8Motion = "none" | "subtle" | "signature";
export type V8Tone = "paper" | "ink" | "sand" | "steel";

export type V8Action = {
  type: string;
  source: string;
  section: string;
  payload?: Record<string, unknown>;
};

export const V8_ROUTES = {
  home: "/",
  about: "/about",
  legacy: "/about/legacy",
  capabilities: "/capabilities",
  work: "/work",
  engineering: "/engineering",
  quality: "/quality-safety",
  careers: "/careers",
  contact: "/contact",
} as const;

export const V8_DESIGN_TOKENS = {
  paper: "#F4F1E9",
  ink: "#111315",
  muted: "#77736B",
  accent: "#B9892F",
  blueprint: "#192737",
  steel: "#DCE1E3",
  line: "rgba(17,19,21,.14)",
  maxWidth: 1180,
  headerHeight: 82,
  heroMinHeight: "100svh",
  motionFast: 180,
  motionMedium: 420,
  motionSlow: 760,
} as const;

export function cx(...values: Array<string | false | null | undefined>) {
  return values.filter(Boolean).join(" ");
}

export function clamp(value: number, min: number, max: number) {
  return Math.max(min, Math.min(max, value));
}

export function progressFromRect(top: number, height: number, viewport: number) {
  if (height <= 0 || viewport <= 0) return 0;
  return clamp((viewport - top) / (viewport + height), 0, 1);
}

export function motionMode(prefersReducedMotion: boolean, requested: V8Motion): V8Motion {
  return prefersReducedMotion ? "none" : requested;
}

export function formatIndex(index: number) {
  return String(Math.max(0, index) + 1).padStart(2, "0");
}

export function publishLabel(state: V8PublicationState) {
  if (state === "verified") return "VERIFIED";
  if (state === "client-supplied") return "CLIENT SUPPLIED / CONFIRM";
  return "PENDING REVIEW";
}

export function makeAction(section: string, type: string, payload?: Record<string, unknown>): V8Action {
  return { type, source: "miror-v8", section, payload };
}

export function isSafeProjectClaim(text: string) {
  const risky = ["best", "largest", "award-winning", "guaranteed", "iso certified", "zero incidents", "100+ projects", "500+ projects"];
  const value = text.toLowerCase();
  return !risky.some((term) => value.includes(term));
}

export function safeProjectText(text: string) {
  return isSafeProjectClaim(text) ? text : "Client confirmation required before publication.";
}

